  const len = ab[0] ** 2 + ab[1] ** 2 + ab[2] ** 2;
  const t = len === 0 ? 0 : Math.max(0, Math.min(1, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / len));
