    finMesh.rotation.z = 0;
    const finGroup = new THREE.Group();
    finGroup.add(finMesh);
    finGroup.rotation.set(0, 0, 0);
    finMesh.geometry.rotateY(Math.PI / 2);
    finMesh.rotation.set(0, Math.PI / 2, 0);
    const finPlane = new THREE.Mesh(
      new THREE.ShapeGeometry(fin),
      this.turtleMat,
    );
