    finPlane.geometry.rotateY(-Math.PI / 2);
    finPlane.geometry.rotateX(0);
    finPlane.rotation.set(0, 0, 0);
    const finFix = new THREE.Group();
    const fm = new THREE.Mesh(new THREE.ShapeGeometry(fin), this.turtleMat);
