  private buildGrid() {
    this.grid.clear();
    const size = 1000, step = 20;
    const minor: number[] = [], major: number[] = [];
    for (let v = -size; v <= size; v += step) {
      const arr = v % 100 === 0 ? major : minor;
      arr.push(v, -size, 0, v, size, 0, -size, v, 0, size, v, 0);
