/* Logomocja — a drafting sheet with a live title block.
   Pen green is the action colour; copying-pencil violet marks only what is executing now. */

:root {
  color-scheme: light;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --ground: #e9eee9;        /* app ground behind panels */
  --panel: #f8faf7;         /* editor and pages */
  --panel-2: #eef2ee;       /* bars */
  --sheet: #f6f8f2;         /* drafting sheet */
  --grid-minor: rgba(22, 134, 106, 0.09);
  --grid-major: rgba(22, 134, 106, 0.2);
  --grid-axis: rgba(27, 36, 34, 0.55);
  --frame: #9aa8a2;
  --ink: #1b2422;
  --ink-2: #4c5955;
  --ink-3: #6c7873;
  --line: #cfd8d3;
  --line-strong: #aab7b1;

  --rail: #123a31;
  --rail-ink: #e6f0eb;
  --rail-ink-2: #a9c4ba;
  --rail-hover: #1b4b40;

  --pen: #16866a;
  --action: #12765d;
  --action-hover: #0f6650;
  --on-action: #ffffff;
  --active: #6a3fb5;
  --active-soft: rgba(106, 63, 181, 0.12);
  --on-active: #ffffff;
  --error: #b3372c;
  --error-soft: #fbe9e6;
  --ok: #12765d;
  --ok-soft: #e3f2ec;
  --warn: #8a5a00;
  --warn-soft: #fbf0d9;

  --syn-cmd: #12765d;
  --syn-struct: #0d5a47;
  --syn-num: #9c4a14;
  --syn-name: #285a9c;
  --syn-str: #7a5a10;
  --syn-com: #6a7672;
  --syn-punct: #4c5955;
  --syn-rep: #6a3fb5;

  --radius: 8px;
  --radius-s: 6px;
  --shadow: 0 6px 24px rgba(18, 40, 33, 0.16), 0 1px 3px rgba(18, 40, 33, 0.12);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #2b6fb3;
  --rail-h: 52px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --ground: #0c1210;
    --panel: #131b18;
    --panel-2: #18221e;
    --sheet: #101714;
    --grid-minor: rgba(98, 214, 172, 0.07);
    --grid-major: rgba(98, 214, 172, 0.16);
    --grid-axis: rgba(220, 235, 228, 0.5);
    --frame: #3a4a44;
    --ink: #e2ebe6;
    --ink-2: #a8b8b1;
    --ink-3: #8a9a93;
    --line: #26332e;
    --line-strong: #3a4a44;
    --rail: #0b1f1a;
    --rail-ink: #e2efe9;
    --rail-ink-2: #93b3a7;
    --rail-hover: #143129;
    --pen: #3fbf98;
    --action: #1e9b7a;
    --action-hover: #23ad89;
    --on-action: #04140f;
    --active: #b49cf2;
    --active-soft: rgba(180, 156, 242, 0.16);
    --on-active: #1a1030;
    --error: #ff8f7f;
    --error-soft: #3a1c18;
    --ok: #5fd3ac;
    --ok-soft: #12302a;
    --warn: #f0c060;
    --warn-soft: #33290f;
    --syn-cmd: #5fd3ac;
    --syn-struct: #8fe6c6;
    --syn-num: #f0a46a;
    --syn-name: #8fb8f0;
    --syn-str: #e6c36a;
    --syn-com: #84958e;
    --syn-punct: #a8b8b1;
    --syn-rep: #c4b0f6;
    --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
    --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --ground: #0c1210;
  --panel: #131b18;
  --panel-2: #18221e;
  --sheet: #101714;
  --grid-minor: rgba(98, 214, 172, 0.07);
  --grid-major: rgba(98, 214, 172, 0.16);
  --grid-axis: rgba(220, 235, 228, 0.5);
  --frame: #3a4a44;
  --ink: #e2ebe6;
  --ink-2: #a8b8b1;
  --ink-3: #8a9a93;
  --line: #26332e;
  --line-strong: #3a4a44;
  --rail: #0b1f1a;
  --rail-ink: #e2efe9;
  --rail-ink-2: #93b3a7;
  --rail-hover: #143129;
  --pen: #3fbf98;
  --action: #1e9b7a;
  --action-hover: #23ad89;
  --on-action: #04140f;
  --active: #b49cf2;
  --active-soft: rgba(180, 156, 242, 0.16);
  --on-active: #1a1030;
  --error: #ff8f7f;
  --error-soft: #3a1c18;
  --ok: #5fd3ac;
  --ok-soft: #12302a;
  --warn: #f0c060;
  --warn-soft: #33290f;
  --syn-cmd: #5fd3ac;
  --syn-struct: #8fe6c6;
  --syn-num: #f0a46a;
  --syn-name: #8fb8f0;
  --syn-str: #e6c36a;
  --syn-com: #84958e;
  --syn-punct: #a8b8b1;
  --syn-rep: #c4b0f6;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  font: 15px/1.5 var(--font);
  color: var(--ink);
  background: var(--ground);
  font-variant-numeric: tabular-nums;
}
::selection { background: color-mix(in srgb, var(--pen) 28%, transparent); }
a { color: var(--syn-name); text-underline-offset: 3px; }
code, kbd, pre { font-family: var(--mono); font-size: 0.92em; }
h1, h2, h3 { line-height: 1.25; text-wrap: balance; margin: 0; }
button, input, select { font: inherit; color: inherit; }
:focus-visible { outline: none; box-shadow: var(--focus); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip {
  position: absolute; left: 8px; top: -48px; z-index: 50; padding: 8px 12px; border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
}
.skip:focus { top: 8px; }
* { scrollbar-color: var(--line-strong) transparent; scrollbar-width: thin; }
svg.ico { width: 18px; height: 18px; flex: none; }

/* ---------- rail ---------- */
.rail {
  height: var(--rail-h);
  display: flex; align-items: center; gap: 24px;
  padding: 0 16px;
  background: var(--rail);
  color: var(--rail-ink);
  position: sticky; top: 0; z-index: 20;
}
.wordmark {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--rail-ink); text-decoration: none;
  font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
  padding: 6px 4px; border-radius: var(--radius-s);
}
.wordmark .mark { color: #3fbf98; transform: rotate(0deg); }
.rail :focus-visible { box-shadow: 0 0 0 2px var(--rail), 0 0 0 4px #9fd8c4; }
.rail-nav { display: flex; gap: 2px; height: 100%; }
.rail-nav a {
  display: inline-flex; align-items: center; padding: 0 12px; height: 100%;
  color: var(--rail-ink-2); text-decoration: none; font-weight: 500;
  border-bottom: 2px solid transparent; border-top: 2px solid transparent;
}
.rail-nav a:hover { color: var(--rail-ink); background: var(--rail-hover); }
.rail-nav a[aria-current="page"] { color: var(--rail-ink); border-bottom-color: #3fbf98; }
.theme-btn {
  margin-left: auto; display: inline-flex; align-items: center; gap: 6px;
  background: transparent; border: 1px solid rgba(255, 255, 255, 0.18); color: var(--rail-ink);
  height: 34px; padding: 0 10px; border-radius: var(--radius-s); cursor: pointer;
}
.theme-btn:hover { background: var(--rail-hover); }

main { outline: none; }

/* ---------- buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 36px; padding: 0 12px;
  border: 1px solid var(--line-strong); border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink);
  font-weight: 500; cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn:hover { background: var(--panel-2); border-color: var(--ink-3); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }
.btn.primary { background: var(--action); border-color: var(--action); color: var(--on-action); font-weight: 600; }
.btn.primary:hover { background: var(--action-hover); border-color: var(--action-hover); }
.btn.ghost { border-color: transparent; background: transparent; }
.btn.ghost:hover { background: var(--panel-2); }
.btn.icon-only { width: 36px; padding: 0; }
.btn.small { height: 30px; padding: 0 10px; font-size: 13.5px; }
.link-btn {
  background: none; border: 0; padding: 2px 4px; color: inherit; font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px; cursor: pointer; border-radius: 4px;
}

/* ---------- studio ---------- */
body[data-route="studio"] { height: 100dvh; overflow: hidden; }
.studio {
  height: calc(100dvh - var(--rail-h));
  display: grid;
  grid-template-columns: minmax(340px, 40%) 1fr;
  grid-template-rows: 1fr auto;
  grid-template-areas: "code sheet" "dock sheet";
}
.pane-switch { display: none; }
.code-pane {
  grid-area: code; min-height: 0; display: flex; flex-direction: column;
  background: var(--panel); border-right: 1px solid var(--line);
}
.code-bar {
  display: flex; align-items: center; gap: 8px; padding: 8px 10px;
  background: var(--panel-2); border-bottom: 1px solid var(--line);
}
.bar-gap { flex: 1; }
.file-actions { display: flex; gap: 2px; }
.file-actions .btn { border-color: transparent; background: transparent; }
.file-actions .btn:hover { background: var(--panel); border-color: var(--line-strong); }
.seg { display: inline-flex; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; height: 36px; }
.seg button {
  border: 0; background: var(--panel); padding: 0 14px; font-weight: 600; cursor: pointer; color: var(--ink-2);
}
.seg button + button { border-left: 1px solid var(--line-strong); }
.seg button[aria-checked="true"] { background: var(--ink); color: var(--panel); }
.seg button:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.editor-slot { flex: 1; min-height: 0; display: flex; }

.dock { grid-area: dock; background: var(--panel); border-right: 1px solid var(--line); border-top: 1px solid var(--line); }
.status {
  display: flex; align-items: flex-start; gap: 8px; padding: 8px 12px; min-height: 40px;
  font-size: 13.5px; color: var(--ink-2); border-bottom: 1px solid var(--line);
}
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--line-strong); margin-top: 6px; flex: none; }
.status-text { flex: 1; }
.status[data-kind="run"] .status-dot, .status[data-kind="pause"] .status-dot { background: var(--active); }
.status[data-kind="ok"] .status-dot { background: var(--ok); }
.status[data-kind="warn"] { color: var(--warn); background: var(--warn-soft); }
.status[data-kind="warn"] .status-dot { background: var(--warn); }
.status[data-kind="error"] { color: var(--error); background: var(--error-soft); }
.status[data-kind="error"] .status-dot { background: var(--error); }
.status[data-kind="error"] .status-text { color: var(--ink); }
.run-bar { display: flex; align-items: center; gap: 6px; padding: 10px; flex-wrap: wrap; }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--ink-2); }
.speed input { width: 110px; accent-color: var(--action); }
.studio[data-run="running"] [data-act="run"] { box-shadow: inset 0 -3px 0 var(--active); }

/* ---------- editor ---------- */
.editor { flex: 1; min-height: 0; display: flex; position: relative; background: var(--panel); }
.ed-scroll { flex: 1; overflow: auto; display: flex; align-items: flex-start; min-height: 0; }
.ed-gutter {
  position: sticky; left: 0; z-index: 2; flex: none;
  min-width: 44px; padding: 12px 8px 40px 0; min-height: 100%;
  background: var(--panel); border-right: 1px solid var(--line);
  font: 13.5px/21px var(--mono); color: var(--ink-3); text-align: right;
  user-select: none;
}
.ed-gutter span { display: block; }
.ed-gutter .g-err { color: var(--error); font-weight: 700; }
.ed-code { position: relative; flex: 1; min-width: max-content; min-height: 100%; }
.ed-hl, .ed-input {
  margin: 0; padding: 12px 16px 40px 12px; border: 0;
  font: 13.5px/21px var(--mono); tab-size: 2; white-space: pre; letter-spacing: 0;
}
.ed-hl { color: var(--ink); pointer-events: none; min-height: 100%; position: relative; z-index: 1; }
.ed-input {
  position: absolute; inset: 0; width: 100%; height: 100%; resize: none; overflow: hidden;
  background: transparent; color: transparent; caret-color: var(--ink); z-index: 2; outline: none;
}
.ed-input::selection { background: color-mix(in srgb, var(--pen) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px #2b6fb3; }
.ed-band {
  position: absolute; left: 0; right: 0; z-index: 0;
  background: var(--active-soft); box-shadow: inset 3px 0 0 var(--active);
}
.ed-bubble {
  position: absolute; z-index: 3; left: calc(12px + var(--col, 0) * 1ch); max-width: min(46ch, 80vw);
  padding: 6px 10px; border-radius: var(--radius-s);
  background: var(--error); color: #fff; font: 600 12.5px/1.4 var(--font); white-space: normal;
  box-shadow: var(--shadow); pointer-events: none;
}
:root[data-theme="dark"] .ed-bubble { color: #2a0d09; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .ed-bubble { color: #2a0d09; } }
.ed-bubble::before {
  content: ""; position: absolute; left: 8px; top: -5px; width: 10px; height: 10px;
  background: inherit; transform: rotate(45deg);
}
.t-k { color: var(--syn-cmd); font-weight: 600; }
.t-k2 { color: var(--syn-struct); font-weight: 700; }
.t-v { color: var(--syn-rep); font-weight: 600; }
.t-n { color: var(--syn-name); }
.t-num { color: var(--syn-num); }
.t-s { color: var(--syn-str); box-shadow: inset 0 -3px 0 var(--sw, transparent); }
.t-bad { text-decoration: underline wavy var(--error); }
.t-c { color: var(--syn-com); font-style: italic; }
.t-b { color: var(--ink); font-weight: 700; }
.t-p, .t-o { color: var(--syn-punct); }
.t-x { color: var(--error); }
.t-err { text-decoration: underline wavy var(--error) 1.5px; text-underline-offset: 4px; background: color-mix(in srgb, var(--error) 14%, transparent); border-radius: 2px; }

/* ---------- sheet ---------- */
.sheet-pane { grid-area: sheet; min-width: 0; min-height: 0; padding: 12px; background: var(--ground); display: flex; }
.sheet {
  position: relative; flex: 1; min-height: 0; overflow: hidden;
  background: var(--sheet); border: 1px solid var(--frame); border-radius: 2px;
  box-shadow: 0 1px 2px rgba(18, 40, 33, 0.08);
}
.sheet::after { content: ""; position: absolute; inset: 6px; border: 1px solid var(--frame); pointer-events: none; opacity: 0.6; }
.sheet-host { position: absolute; inset: 0; }
.sheet-host[hidden] { display: none; }
.sheet-canvas { display: block; touch-action: none; cursor: grab; outline: none; }
.sheet-canvas:active { cursor: grabbing; }
.sheet-canvas:focus-visible { box-shadow: inset 0 0 0 3px #2b6fb3; }
.nogl { position: absolute; inset: 0; display: grid; place-items: center; padding: 24px; }
.nogl[hidden] { display: none; }
.nogl p { max-width: 42ch; margin: 0; padding: 16px 18px; border: 1px solid var(--line-strong); background: var(--panel); border-radius: var(--radius); }
.view-tools {
  position: absolute; top: 16px; right: 16px; z-index: 3;
  display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line-strong);
  border-radius: var(--radius-s); box-shadow: 0 2px 8px rgba(18, 40, 33, 0.12); overflow: hidden;
}
.tool { width: 38px; height: 38px; display: grid; place-items: center; border: 0; background: none; cursor: pointer; color: var(--ink); }
.tool + .tool { border-top: 1px solid var(--line); }
.tool:hover { background: var(--panel-2); }
.tool:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.tool[hidden] { display: none; }

/* The title block: a ruled drafting tabliczka holding live readouts. */
.title-block {
  position: absolute; right: 16px; bottom: 16px; z-index: 3; margin: 0;
  display: grid; grid-template-columns: repeat(4, auto);
  background: var(--sheet); border: 1.5px solid var(--ink);
  font-size: 12px; line-height: 1.25; pointer-events: none;
}
.title-block > div { padding: 4px 8px 5px; border-right: 1px solid var(--ink); border-top: 1px solid var(--ink); min-width: 64px; }
.title-block > div:nth-child(4n), .title-block > .tb-name { border-right: 0; }
.title-block > .tb-name { grid-column: 1 / -1; border-top: 0; display: flex; align-items: baseline; gap: 10px; padding: 6px 8px; }
.title-block > .tb-wide { grid-column: span 2; }
.title-block > div:nth-child(5) { border-right: 1px solid var(--ink); }
.title-block > div:last-child { border-right: 0; grid-column: span 2; }
.title-block dt { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-2); }
.title-block dd { margin: 0; font-weight: 600; white-space: nowrap; }
.title-block .tb-name dd { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
[data-tb="pen"]::before { content: ""; display: inline-block; width: 10px; height: 10px; margin-right: 6px; vertical-align: -1px; background: var(--pen, #16866a); border: 1px solid var(--ink); }
.title-block dd[data-tb="pen"] { --pen: #16866a; }
.studio[data-run="running"] .title-block, .studio[data-run="paused"] .title-block { border-color: var(--active); }
.studio[data-run="running"] .title-block [data-tb="pos"], .studio[data-run="paused"] .title-block [data-tb="pos"] { color: var(--active); }

/* ---------- popovers ---------- */
.pop {
  margin: auto; padding: 0; border: 1px solid var(--line-strong); border-radius: 12px;
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
  width: min(760px, calc(100vw - 24px)); max-height: min(720px, calc(100dvh - 32px)); overflow: auto;
}
.pop::backdrop { background: rgba(10, 20, 17, 0.32); }
.pop-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px 6px 20px; position: sticky; top: 0; background: var(--panel); z-index: 1; }
.pop-head h2 { font-size: 18px; }
.pop-note { margin: 0 20px 12px; color: var(--ink-2); font-size: 13.5px; }
.ex-grid {
  list-style: none; margin: 0; padding: 0 16px 16px;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 10px;
}
.ex-cell {
  width: 100%; height: 100%; display: flex; flex-direction: column; gap: 2px; text-align: left;
  padding: 6px 6px 10px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); cursor: pointer;
}
.ex-cell:hover { border-color: var(--pen); }
.ex-thumb { width: 100%; height: 104px; display: block; border-radius: 4px; margin-bottom: 6px; background: var(--sheet); }
.ex-name { display: flex; justify-content: space-between; align-items: baseline; font-weight: 650; padding: 0 4px; }
.ex-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); border: 1px solid var(--line-strong); border-radius: 4px; padding: 0 4px; }
.ex-blurb { font-size: 12.5px; color: var(--ink-2); padding: 0 4px; }
.restore { margin: 0 16px 16px; }
.restore[hidden] { display: none; }
.shortcuts-pop { width: min(480px, calc(100vw - 24px)); }
.keys { margin: 0; padding: 4px 20px 18px; display: grid; gap: 8px; }
.keys > div { display: grid; grid-template-columns: minmax(160px, auto) 1fr; gap: 12px; align-items: baseline; }
.keys dt, .keys dd { margin: 0; }
kbd {
  display: inline-block; padding: 1px 6px; border: 1px solid var(--line-strong); border-bottom-width: 2px;
  border-radius: 4px; background: var(--panel-2); font-size: 12.5px; white-space: nowrap;
}

/* ---------- toasts ---------- */
.toasts { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); z-index: 60; display: grid; gap: 8px; width: min(520px, calc(100vw - 24px)); }
.toast {
  display: flex; align-items: center; gap: 10px; padding: 10px 8px 10px 14px;
  background: var(--ink); color: var(--panel); border-radius: var(--radius); box-shadow: var(--shadow);
  animation: toast-in 200ms cubic-bezier(0.16, 1, 0.3, 1);
}
.toast p { margin: 0; flex: 1; font-size: 14px; }
.toast .btn { background: transparent; color: var(--panel); border-color: color-mix(in srgb, var(--panel) 45%, transparent); }
.toast .btn:hover { background: color-mix(in srgb, var(--panel) 14%, transparent); }
.toast-x { background: none; border: 0; color: inherit; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 4px; cursor: pointer; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- pages ---------- */
.page { max-width: 1200px; margin: 0 auto; padding: 28px 24px 64px; display: grid; gap: 32px; }
.page h1 { font-size: 24px; letter-spacing: -0.015em; }

.challenges { grid-template-columns: 260px 1fr; align-items: start; }
.ch-list { position: sticky; top: calc(var(--rail-h) + 24px); }
.ch-count { color: var(--ink-2); margin: 4px 0 14px; font-size: 14px; }
.ch-list ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.ch-list a {
  display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: var(--radius-s); color: var(--ink); text-decoration: none;
}
.ch-list a:hover { background: var(--panel-2); }
.ch-list a[aria-current="page"] { background: var(--panel); box-shadow: inset 0 0 0 1px var(--line-strong); font-weight: 600; }
.ch-state { width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--line-strong); display: grid; place-items: center; }
.ch-state.is-done { background: var(--ok); border-color: var(--ok); color: var(--panel); }
.ch-state svg { width: 14px; height: 14px; }
.ch-li-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); }
.ch-detail { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 24px; min-width: 0; }
.ch-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.ch-name { font-size: 22px; letter-spacing: -0.01em; }
.ch-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 700; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-strong); color: var(--ink-2); }
.ch-badge.is-done { background: var(--ok-soft); border-color: var(--ok); color: var(--ok); }
.ch-badge svg { width: 14px; height: 14px; }
.ch-task { font-size: 16px; max-width: 65ch; margin: 10px 0 8px; }
.ch-hint { margin-bottom: 18px; color: var(--ink-2); }
.ch-hint summary { cursor: pointer; font-weight: 600; width: max-content; border-radius: 4px; }
.ch-hint p { margin: 6px 0 0; max-width: 65ch; }
.ch-work { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; }
.ch-figure { margin: 0; }
.ch-canvas { width: 100%; aspect-ratio: 4 / 3; display: block; border: 1px solid var(--frame); background: var(--sheet); }
.ch-figure figcaption { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 13px; color: var(--ink-2); }
.key-target, .key-attempt { display: inline-block; width: 22px; height: 0; border-top: 2px dashed var(--ink-2); }
.key-attempt { border-top: 3px solid var(--pen); margin-left: 12px; }
.ch-code { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.ch-code .editor { min-height: 240px; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; }
.ch-code .ed-scroll { max-height: 420px; }
.ch-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ch-result:empty { display: none; }
.ch-result { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius); }
.ch-result p { margin: 0; }
.ch-result[data-kind="ok"] { background: var(--ok-soft); color: var(--ink); }
.ch-result[data-kind="ok"] svg { color: var(--ok); }
.ch-result[data-kind="fail"] { background: var(--error-soft); color: var(--ink); }
.ch-result[data-kind="fail"] svg { color: var(--error); }

.help { grid-template-columns: 240px minmax(0, 1fr); align-items: start; }
.help-toc { position: sticky; top: calc(var(--rail-h) + 24px); }
.help-toc h1 { font-size: 20px; margin-bottom: 12px; }
.help-toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; border-left: 1px solid var(--line); }
.help-toc a { display: block; padding: 5px 12px; color: var(--ink-2); text-decoration: none; margin-left: -1px; border-left: 2px solid transparent; }
.help-toc a:hover { color: var(--ink); border-left-color: var(--pen); }
.help-body { max-width: 80ch; display: grid; gap: 40px; }
.help-body section { scroll-margin-top: calc(var(--rail-h) + 20px); }
.help-body h2 { font-size: 21px; letter-spacing: -0.01em; margin: 0 0 10px; outline: none; }
.help-body p, .help-body li { max-width: 70ch; }
.help-body ul { padding-left: 20px; }
.help-body li { margin: 4px 0; }
.help-body :not(pre) > code { background: var(--panel-2); padding: 1px 5px; border-radius: 4px; border: 1px solid var(--line); }
.cmd-list { display: grid; gap: 0; border-top: 1px solid var(--line); }
.cmd { padding: 18px 0; border-bottom: 1px solid var(--line); }
.cmd h3 { font-size: 16px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cmd h3 code { color: var(--syn-cmd); font-weight: 700; font-size: 15px; }
.tag { font-size: 11px; font-weight: 700; padding: 1px 6px; border: 1px solid var(--line-strong); border-radius: 4px; color: var(--ink-2); }
.cmd-meta { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 13.5px; color: var(--ink-2); margin: 6px 0; }
.cmd p { margin: 6px 0; }
.example { display: flex; align-items: flex-end; gap: 12px; margin-top: 10px; flex-wrap: wrap; }
.example pre { margin: 0; flex: 1; min-width: 220px; padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-s); overflow-x: auto; line-height: 1.6; }
.limits { border-collapse: collapse; width: 100%; margin-top: 12px; font-size: 14px; }
.limits caption { text-align: left; font-weight: 700; padding-bottom: 6px; }
.limits th, .limits td { text-align: left; vertical-align: top; padding: 8px 10px; border-top: 1px solid var(--line); }
.limits th { font-weight: 600; width: 40%; }

/* ---------- responsive ---------- */
@media (max-width: 1100px) {
  .speed-label { display: none; }
  .speed input { width: 84px; }
}
@media (max-width: 860px) {
  :root { --rail-h: 48px; }
  .rail { gap: 8px; padding: 0 8px; }
  .wordmark span { display: none; }
  .rail-nav a { padding: 0 10px; }
  .theme-label { display: none; }
  .theme-btn { width: 36px; justify-content: center; padding: 0; }
  .studio {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "switch" "pane" "dock";
  }
  .pane-switch {
    grid-area: switch; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 6px 8px;
    background: var(--panel-2); border-bottom: 1px solid var(--line);
  }
  .pane-switch button {
    display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px;
    border: 1px solid transparent; border-radius: var(--radius-s); background: transparent; font-weight: 600; color: var(--ink-2); cursor: pointer;
  }
  .pane-switch button[aria-selected="true"] { background: var(--panel); border-color: var(--line-strong); color: var(--ink); }
  .code-pane, .sheet-pane { grid-area: pane; border-right: 0; }
  .studio[data-pane="code"] .sheet-pane { visibility: hidden; pointer-events: none; }
  .studio[data-pane="sheet"] .code-pane { display: none; }
  .sheet-pane { padding: 6px; }
  .dock { border-right: 0; padding-bottom: env(safe-area-inset-bottom); }
  .run-bar { padding: 8px; gap: 4px; flex-wrap: nowrap; }
  .run-bar .btn { padding: 0 10px; }
  .run-bar .btn:not(.primary) span { display: none; }
  .run-bar .btn:not(.primary) { width: 40px; padding: 0; }
  .speed { margin-left: auto; }
  .speed input { width: 72px; }
  .status { min-height: 0; padding: 6px 10px; font-size: 13px; }
  .title-block { right: 10px; bottom: 10px; grid-template-columns: repeat(2, auto); font-size: 11px; }
  .title-block > div:nth-child(n) { border-right: 1px solid var(--ink); grid-column: auto; }
  .title-block > div:nth-child(2n+1):not(.tb-name) { border-right: 0; }
  .title-block > .tb-name { grid-column: 1 / -1; border-right: 0; }
  .title-block > .tb-wide, .title-block > div:last-child { grid-column: auto; }
  .title-block > div:nth-child(6), .title-block > div:nth-child(7) { display: none; }
  .view-tools { top: 10px; right: 10px; }
  .page { padding: 18px 14px 48px; gap: 20px; }
  .challenges, .help { grid-template-columns: 1fr; }
  .ch-list, .help-toc { position: static; }
  .ch-work { grid-template-columns: 1fr; }
  .ch-detail { padding: 16px; }
  .help-toc ol { display: flex; flex-wrap: wrap; border-left: 0; gap: 4px; }
  .help-toc a { border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; margin: 0; font-size: 13.5px; }
}
@media (max-width: 420px) {
  .code-bar { gap: 4px; padding: 6px; }
  #examples-btn span { display: none; }
  #examples-btn { width: 36px; padding: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

@media (forced-colors: active) {
  .ed-input { color: CanvasText; }
  .ed-hl { visibility: hidden; }
}

toolu_01SixxyxPb6en8viQPdd8sdd.content:
/* Logomocja — a drafting sheet with a live title block.
   Pen green is the action colour; copying-pencil violet marks only what is executing now. */

:root {
  color-scheme: light;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --ground: #e9eee9;        /* app ground behind panels */
  --panel: #f8faf7;         /* editor and pages */
  --panel-2: #eef2ee;       /* bars */
  --sheet: #f6f8f2;         /* drafting sheet */
  --grid-minor: rgba(22, 134, 106, 0.09);
  --grid-major: rgba(22, 134, 106, 0.2);
  --grid-axis: rgba(27, 36, 34, 0.55);
  --frame: #9aa8a2;
  --ink: #1b2422;
  --ink-2: #4c5955;
  --ink-3: #6c7873;
  --line: #cfd8d3;
  --line-strong: #aab7b1;

  --rail: #123a31;
  --rail-ink: #e6f0eb;
  --rail-ink-2: #a9c4ba;
  --rail-hover: #1b4b40;

  --pen: #16866a;
  --action: #12765d;
  --action-hover: #0f6650;
  --on-action: #ffffff;
  --active: #6a3fb5;
  --active-soft: rgba(106, 63, 181, 0.12);
  --on-active: #ffffff;
  --error: #b3372c;
  --error-soft: #fbe9e6;
  --ok: #12765d;
  --ok-soft: #e3f2ec;
  --warn: #8a5a00;
  --warn-soft: #fbf0d9;

  --syn-cmd: #12765d;
  --syn-struct: #0d5a47;
  --syn-num: #9c4a14;
  --syn-name: #285a9c;
  --syn-str: #7a5a10;
  --syn-com: #6a7672;
  --syn-punct: #4c5955;
  --syn-rep: #6a3fb5;

  --radius: 8px;
  --radius-s: 6px;
  --shadow: 0 6px 24px rgba(18, 40, 33, 0.16), 0 1px 3px rgba(18, 40, 33, 0.12);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #2b6fb3;
  --rail-h: 52px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --ground: #0c1210;
    --panel: #131b18;
    --panel-2: #18221e;
    --sheet: #101714;
    --grid-minor: rgba(98, 214, 172, 0.07);
    --grid-major: rgba(98, 214, 172, 0.16);
    --grid-axis: rgba(220, 235, 228, 0.5);
    --frame: #3a4a44;
    --ink: #e2ebe6;
    --ink-2: #a8b8b1;
    --ink-3: #8a9a93;
    --line: #26332e;
    --line-strong: #3a4a44;
    --rail: #0b1f1a;
    --rail-ink: #e2efe9;
    --rail-ink-2: #93b3a7;
    --rail-hover: #143129;
    --pen: #3fbf98;
    --action: #1e9b7a;
    --action-hover: #23ad89;
    --on-action: #04140f;
    --active: #b49cf2;
    --active-soft: rgba(180, 156, 242, 0.16);
    --on-active: #1a1030;
    --error: #ff8f7f;
    --error-soft: #3a1c18;
    --ok: #5fd3ac;
    --ok-soft: #12302a;
    --warn: #f0c060;
    --warn-soft: #33290f;
    --syn-cmd: #5fd3ac;
    --syn-struct: #8fe6c6;
    --syn-num: #f0a46a;
    --syn-name: #8fb8f0;
    --syn-str: #e6c36a;
    --syn-com: #84958e;
    --syn-punct: #a8b8b1;
    --syn-rep: #c4b0f6;
    --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
    --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --ground: #0c1210;
  --panel: #131b18;
  --panel-2: #18221e;
  --sheet: #101714;
  --grid-minor: rgba(98, 214, 172, 0.07);
  --grid-major: rgba(98, 214, 172, 0.16);
  --grid-axis: rgba(220, 235, 228, 0.5);
  --frame: #3a4a44;
  --ink: #e2ebe6;
  --ink-2: #a8b8b1;
  --ink-3: #8a9a93;
  --line: #26332e;
  --line-strong: #3a4a44;
  --rail: #0b1f1a;
  --rail-ink: #e2efe9;
  --rail-ink-2: #93b3a7;
  --rail-hover: #143129;
  --pen: #3fbf98;
  --action: #1e9b7a;
  --action-hover: #23ad89;
  --on-action: #04140f;
  --active: #b49cf2;
  --active-soft: rgba(180, 156, 242, 0.16);
  --on-active: #1a1030;
  --error: #ff8f7f;
  --error-soft: #3a1c18;
  --ok: #5fd3ac;
  --ok-soft: #12302a;
  --warn: #f0c060;
  --warn-soft: #33290f;
  --syn-cmd: #5fd3ac;
  --syn-struct: #8fe6c6;
  --syn-num: #f0a46a;
  --syn-name: #8fb8f0;
  --syn-str: #e6c36a;
  --syn-com: #84958e;
  --syn-punct: #a8b8b1;
  --syn-rep: #c4b0f6;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  font: 15px/1.5 var(--font);
  color: var(--ink);
  background: var(--ground);
  font-variant-numeric: tabular-nums;
}
::selection { background: color-mix(in srgb, var(--pen) 28%, transparent); }
a { color: var(--syn-name); text-underline-offset: 3px; }
code, kbd, pre { font-family: var(--mono); font-size: 0.92em; }
h1, h2, h3 { line-height: 1.25; text-wrap: balance; margin: 0; }
button, input, select { font: inherit; color: inherit; }
:focus-visible { outline: none; box-shadow: var(--focus); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip {
  position: absolute; left: 8px; top: -48px; z-index: 50; padding: 8px 12px; border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
}
.skip:focus { top: 8px; }
* { scrollbar-color: var(--line-strong) transparent; scrollbar-width: thin; }
svg.ico { width: 18px; height: 18px; flex: none; }

/* ---------- rail ---------- */
.rail {
  height: var(--rail-h);
  display: flex; align-items: center; gap: 24px;
  padding: 0 16px;
  background: var(--rail);
  color: var(--rail-ink);
  position: sticky; top: 0; z-index: 20;
}
.wordmark {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--rail-ink); text-decoration: none;
  font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
  padding: 6px 4px; border-radius: var(--radius-s);
}
.wordmark .mark { color: #3fbf98; transform: rotate(0deg); }
.rail :focus-visible { box-shadow: 0 0 0 2px var(--rail), 0 0 0 4px #9fd8c4; }
.rail-nav { display: flex; gap: 2px; height: 100%; }
.rail-nav a {
  display: inline-flex; align-items: center; padding: 0 12px; height: 100%;
  color: var(--rail-ink-2); text-decoration: none; font-weight: 500;
  border-bottom: 2px solid transparent; border-top: 2px solid transparent;
}
.rail-nav a:hover { color: var(--rail-ink); background: var(--rail-hover); }
.rail-nav a[aria-current="page"] { color: var(--rail-ink); border-bottom-color: #3fbf98; }
.theme-btn {
  margin-left: auto; display: inline-flex; align-items: center; gap: 6px;
  background: transparent; border: 1px solid rgba(255, 255, 255, 0.18); color: var(--rail-ink);
  height: 34px; padding: 0 10px; border-radius: var(--radius-s); cursor: pointer;
}
.theme-btn:hover { background: var(--rail-hover); }

main { outline: none; }

/* ---------- buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 36px; padding: 0 12px;
  border: 1px solid var(--line-strong); border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink);
  font-weight: 500; cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn:hover { background: var(--panel-2); border-color: var(--ink-3); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }
.btn.primary { background: var(--action); border-color: var(--action); color: var(--on-action); font-weight: 600; }
.btn.primary:hover { background: var(--action-hover); border-color: var(--action-hover); }
.btn.ghost { border-color: transparent; background: transparent; }
.btn.ghost:hover { background: var(--panel-2); }
.btn.icon-only { width: 36px; padding: 0; }
.btn.small { height: 30px; padding: 0 10px; font-size: 13.5px; }
.link-btn {
  background: none; border: 0; padding: 2px 4px; color: inherit; font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px; cursor: pointer; border-radius: 4px;
}

/* ---------- studio ---------- */
body[data-route="studio"] { height: 100dvh; overflow: hidden; }
.studio {
  height: calc(100dvh - var(--rail-h));
  display: grid;
  grid-template-columns: minmax(340px, 40%) 1fr;
  grid-template-rows: 1fr auto;
  grid-template-areas: "code sheet" "dock sheet";
}
.pane-switch { display: none; }
.code-pane {
  grid-area: code; min-height: 0; display: flex; flex-direction: column;
  background: var(--panel); border-right: 1px solid var(--line);
}
.code-bar {
  display: flex; align-items: center; gap: 8px; padding: 8px 10px;
  background: var(--panel-2); border-bottom: 1px solid var(--line);
}
.bar-gap { flex: 1; }
.file-actions { display: flex; gap: 2px; }
.file-actions .btn { border-color: transparent; background: transparent; }
.file-actions .btn:hover { background: var(--panel); border-color: var(--line-strong); }
.seg { display: inline-flex; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; height: 36px; }
.seg button {
  border: 0; background: var(--panel); padding: 0 14px; font-weight: 600; cursor: pointer; color: var(--ink-2);
}
.seg button + button { border-left: 1px solid var(--line-strong); }
.seg button[aria-checked="true"] { background: var(--ink); color: var(--panel); }
.seg button:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.editor-slot { flex: 1; min-height: 0; display: flex; }

.dock { grid-area: dock; background: var(--panel); border-right: 1px solid var(--line); border-top: 1px solid var(--line); }
.status {
  display: flex; align-items: flex-start; gap: 8px; padding: 8px 12px; min-height: 40px;
  font-size: 13.5px; color: var(--ink-2); border-bottom: 1px solid var(--line);
}
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--line-strong); margin-top: 6px; flex: none; }
.status-text { flex: 1; }
.status[data-kind="run"] .status-dot, .status[data-kind="pause"] .status-dot { background: var(--active); }
.status[data-kind="ok"] .status-dot { background: var(--ok); }
.status[data-kind="warn"] { color: var(--warn); background: var(--warn-soft); }
.status[data-kind="warn"] .status-dot { background: var(--warn); }
.status[data-kind="error"] { color: var(--error); background: var(--error-soft); }
.status[data-kind="error"] .status-dot { background: var(--error); }
.status[data-kind="error"] .status-text { color: var(--ink); }
.run-bar { display: flex; align-items: center; gap: 6px; padding: 10px; flex-wrap: wrap; }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--ink-2); }
.speed input { width: 110px; accent-color: var(--action); }
.studio[data-run="running"] [data-act="run"] { box-shadow: inset 0 -3px 0 var(--active); }

/* ---------- editor ---------- */
.editor { flex: 1; min-height: 0; display: flex; position: relative; background: var(--panel); }
.ed-scroll { flex: 1; overflow: auto; display: flex; align-items: flex-start; min-height: 0; }
.ed-gutter {
  position: sticky; left: 0; z-index: 2; flex: none;
  min-width: 44px; padding: 12px 8px 40px 0; min-height: 100%;
  background: var(--panel); border-right: 1px solid var(--line);
  font: 13.5px/21px var(--mono); color: var(--ink-3); text-align: right;
  user-select: none;
}
.ed-gutter span { display: block; }
.ed-gutter .g-err { color: var(--error); font-weight: 700; }
.ed-code { position: relative; flex: 1; min-width: max-content; min-height: 100%; }
.ed-hl, .ed-input {
  margin: 0; padding: 12px 16px 40px 12px; border: 0;
  font: 13.5px/21px var(--mono); tab-size: 2; white-space: pre; letter-spacing: 0;
}
.ed-hl { color: var(--ink); pointer-events: none; min-height: 100%; position: relative; z-index: 1; }
.ed-input {
  position: absolute; inset: 0; width: 100%; height: 100%; resize: none; overflow: hidden;
  background: transparent; color: transparent; caret-color: var(--ink); z-index: 2; outline: none;
}
.ed-input::selection { background: color-mix(in srgb, var(--pen) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px #2b6fb3; }
.ed-band {
  position: absolute; left: 0; right: 0; z-index: 0;
  background: var(--active-soft); box-shadow: inset 3px 0 0 var(--active);
}
.ed-bubble {
  position: absolute; z-index: 3; left: calc(12px + var(--col, 0) * 1ch); max-width: min(46ch, 80vw);
  padding: 6px 10px; border-radius: var(--radius-s);
  background: var(--error); color: #fff; font: 600 12.5px/1.4 var(--font); white-space: normal;
  box-shadow: var(--shadow); pointer-events: none;
}
:root[data-theme="dark"] .ed-bubble { color: #2a0d09; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .ed-bubble { color: #2a0d09; } }
.ed-bubble::before {
  content: ""; position: absolute; left: 8px; top: -5px; width: 10px; height: 10px;
  background: inherit; transform: rotate(45deg);
}
.t-k { color: var(--syn-cmd); font-weight: 600; }
.t-k2 { color: var(--syn-struct); font-weight: 700; }
.t-v { color: var(--syn-rep); font-weight: 600; }
.t-n { color: var(--syn-name); }
.t-num { color: var(--syn-num); }
.t-s { color: var(--syn-str); box-shadow: inset 0 -3px 0 var(--sw, transparent); }
.t-bad { text-decoration: underline wavy var(--error); }
.t-c { color: var(--syn-com); font-style: italic; }
.t-b { color: var(--ink); font-weight: 700; }
.t-p, .t-o { color: var(--syn-punct); }
.t-x { color: var(--error); }
.t-err { text-decoration: underline wavy var(--error) 1.5px; text-underline-offset: 4px; background: color-mix(in srgb, var(--error) 14%, transparent); border-radius: 2px; }

/* ---------- sheet ---------- */
.sheet-pane { grid-area: sheet; min-width: 0; min-height: 0; padding: 12px; background: var(--ground); display: flex; }
.sheet {
  position: relative; flex: 1; min-height: 0; overflow: hidden;
  background: var(--sheet); border: 1px solid var(--frame); border-radius: 2px;
  box-shadow: 0 1px 2px rgba(18, 40, 33, 0.08);
}
.sheet::after { content: ""; position: absolute; inset: 6px; border: 1px solid var(--frame); pointer-events: none; opacity: 0.6; }
.sheet-host { position: absolute; inset: 0; }
.sheet-host[hidden] { display: none; }
.sheet-canvas { display: block; touch-action: none; cursor: grab; outline: none; }
.sheet-canvas:active { cursor: grabbing; }
.sheet-canvas:focus-visible { box-shadow: inset 0 0 0 3px #2b6fb3; }
.nogl { position: absolute; inset: 0; display: grid; place-items: center; padding: 24px; }
.nogl[hidden] { display: none; }
.nogl p { max-width: 42ch; margin: 0; padding: 16px 18px; border: 1px solid var(--line-strong); background: var(--panel); border-radius: var(--radius); }
.view-tools {
  position: absolute; top: 16px; right: 16px; z-index: 3;
  display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line-strong);
  border-radius: var(--radius-s); box-shadow: 0 2px 8px rgba(18, 40, 33, 0.12); overflow: hidden;
}
.tool { width: 38px; height: 38px; display: grid; place-items: center; border: 0; background: none; cursor: pointer; color: var(--ink); }
.tool + .tool { border-top: 1px solid var(--line); }
.tool:hover { background: var(--panel-2); }
.tool:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.tool[hidden] { display: none; }

/* The title block: a ruled drafting tabliczka holding live readouts. */
.title-block {
  position: absolute; right: 16px; bottom: 16px; z-index: 3; margin: 0;
  display: grid; grid-template-columns: repeat(4, auto);
  background: var(--sheet); border: 1.5px solid var(--ink);
  font-size: 12px; line-height: 1.25; pointer-events: none;
}
.title-block > div { padding: 4px 8px 5px; border-right: 1px solid var(--ink); border-top: 1px solid var(--ink); min-width: 64px; }
.title-block > div:nth-child(4n), .title-block > .tb-name { border-right: 0; }
.title-block > .tb-name { grid-column: 1 / -1; border-top: 0; display: flex; align-items: baseline; gap: 10px; padding: 6px 8px; }
.title-block > .tb-wide { grid-column: span 2; }
.title-block > div:nth-child(5) { border-right: 1px solid var(--ink); }
.title-block > div:last-child { border-right: 0; grid-column: span 2; }
.title-block dt { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-2); }
.title-block dd { margin: 0; font-weight: 600; white-space: nowrap; }
.title-block .tb-name dd { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
[data-tb="pen"]::before { content: ""; display: inline-block; width: 10px; height: 10px; margin-right: 6px; vertical-align: -1px; background: var(--pen, #16866a); border: 1px solid var(--ink); }
.title-block dd[data-tb="pen"] { --pen: #16866a; }
.studio[data-run="running"] .title-block, .studio[data-run="paused"] .title-block { border-color: var(--active); }
.studio[data-run="running"] .title-block [data-tb="pos"], .studio[data-run="paused"] .title-block [data-tb="pos"] { color: var(--active); }

/* ---------- popovers ---------- */
.pop {
  margin: auto; padding: 0; border: 1px solid var(--line-strong); border-radius: 12px;
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
  width: min(760px, calc(100vw - 24px)); max-height: min(720px, calc(100dvh - 32px)); overflow: auto;
}
.pop::backdrop { background: rgba(10, 20, 17, 0.32); }
.pop-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px 6px 20px; position: sticky; top: 0; background: var(--panel); z-index: 1; }
.pop-head h2 { font-size: 18px; }
.pop-note { margin: 0 20px 12px; color: var(--ink-2); font-size: 13.5px; }
.ex-grid {
  list-style: none; margin: 0; padding: 0 16px 16px;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 10px;
}
.ex-cell {
  width: 100%; height: 100%; display: flex; flex-direction: column; gap: 2px; text-align: left;
  padding: 6px 6px 10px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); cursor: pointer;
}
.ex-cell:hover { border-color: var(--pen); }
.ex-thumb { width: 100%; height: 104px; display: block; border-radius: 4px; margin-bottom: 6px; background: var(--sheet); }
.ex-name { display: flex; justify-content: space-between; align-items: baseline; font-weight: 650; padding: 0 4px; }
.ex-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); border: 1px solid var(--line-strong); border-radius: 4px; padding: 0 4px; }
.ex-blurb { font-size: 12.5px; color: var(--ink-2); padding: 0 4px; }
.restore { margin: 0 16px 16px; }
.restore[hidden] { display: none; }
.shortcuts-pop { width: min(480px, calc(100vw - 24px)); }
.keys { margin: 0; padding: 4px 20px 18px; display: grid; gap: 8px; }
.keys > div { display: grid; grid-template-columns: minmax(160px, auto) 1fr; gap: 12px; align-items: baseline; }
.keys dt, .keys dd { margin: 0; }
kbd {
  display: inline-block; padding: 1px 6px; border: 1px solid var(--line-strong); border-bottom-width: 2px;
  border-radius: 4px; background: var(--panel-2); font-size: 12.5px; white-space: nowrap;
}

/* ---------- toasts ---------- */
.toasts { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); z-index: 60; display: grid; gap: 8px; width: min(520px, calc(100vw - 24px)); }
.toast {
  display: flex; align-items: center; gap: 10px; padding: 10px 8px 10px 14px;
  background: var(--ink); color: var(--panel); border-radius: var(--radius); box-shadow: var(--shadow);
  animation: toast-in 200ms cubic-bezier(0.16, 1, 0.3, 1);
}
.toast p { margin: 0; flex: 1; font-size: 14px; }
.toast .btn { background: transparent; color: var(--panel); border-color: color-mix(in srgb, var(--panel) 45%, transparent); }
.toast .btn:hover { background: color-mix(in srgb, var(--panel) 14%, transparent); }
.toast-x { background: none; border: 0; color: inherit; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 4px; cursor: pointer; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- pages ---------- */
.page { max-width: 1200px; margin: 0 auto; padding: 28px 24px 64px; display: grid; gap: 32px; }
.page h1 { font-size: 24px; letter-spacing: -0.015em; }

.challenges { grid-template-columns: 260px 1fr; align-items: start; }
.ch-list { position: sticky; top: calc(var(--rail-h) + 24px); }
.ch-count { color: var(--ink-2); margin: 4px 0 14px; font-size: 14px; }
.ch-list ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.ch-list a {
  display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: var(--radius-s); color: var(--ink); text-decoration: none;
}
.ch-list a:hover { background: var(--panel-2); }
.ch-list a[aria-current="page"] { background: var(--panel); box-shadow: inset 0 0 0 1px var(--line-strong); font-weight: 600; }
.ch-state { width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--line-strong); display: grid; place-items: center; }
.ch-state.is-done { background: var(--ok); border-color: var(--ok); color: var(--panel); }
.ch-state svg { width: 14px; height: 14px; }
.ch-li-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); }
.ch-detail { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 24px; min-width: 0; }
.ch-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.ch-name { font-size: 22px; letter-spacing: -0.01em; }
.ch-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 700; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-strong); color: var(--ink-2); }
.ch-badge.is-done { background: var(--ok-soft); border-color: var(--ok); color: var(--ok); }
.ch-badge svg { width: 14px; height: 14px; }
.ch-task { font-size: 16px; max-width: 65ch; margin: 10px 0 8px; }
.ch-hint { margin-bottom: 18px; color: var(--ink-2); }
.ch-hint summary { cursor: pointer; font-weight: 600; width: max-content; border-radius: 4px; }
.ch-hint p { margin: 6px 0 0; max-width: 65ch; }
.ch-work { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; }
.ch-figure { margin: 0; }
.ch-canvas { width: 100%; aspect-ratio: 4 / 3; display: block; border: 1px solid var(--frame); background: var(--sheet); }
.ch-figure figcaption { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 13px; color: var(--ink-2); }
.key-target, .key-attempt { display: inline-block; width: 22px; height: 0; border-top: 2px dashed var(--ink-2); }
.key-attempt { border-top: 3px solid var(--pen); margin-left: 12px; }
.ch-code { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.ch-code .editor { min-height: 240px; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; }
.ch-code .ed-scroll { max-height: 420px; }
.ch-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ch-result:empty { display: none; }
.ch-result { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius); }
.ch-result p { margin: 0; }
.ch-result[data-kind="ok"] { background: var(--ok-soft); color: var(--ink); }
.ch-result[data-kind="ok"] svg { color: var(--ok); }
.ch-result[data-kind="fail"] { background: var(--error-soft); color: var(--ink); }
.ch-result[data-kind="fail"] svg { color: var(--error); }

.help { grid-template-columns: 240px minmax(0, 1fr); align-items: start; }
.help-toc { position: sticky; top: calc(var(--rail-h) + 24px); }
.help-toc h1 { font-size: 20px; margin-bottom: 12px; }
.help-toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; border-left: 1px solid var(--line); }
.help-toc a { display: block; padding: 5px 12px; color: var(--ink-2); text-decoration: none; margin-left: -1px; border-left: 2px solid transparent; }
.help-toc a:hover { color: var(--ink); border-left-color: var(--pen); }
.help-body { max-width: 80ch; display: grid; gap: 40px; }
.help-body section { scroll-margin-top: calc(var(--rail-h) + 20px); }
.help-body h2 { font-size: 21px; letter-spacing: -0.01em; margin: 0 0 10px; outline: none; }
.help-body p, .help-body li { max-width: 70ch; }
.help-body ul { padding-left: 20px; }
.help-body li { margin: 4px 0; }
.help-body :not(pre) > code { background: var(--panel-2); padding: 1px 5px; border-radius: 4px; border: 1px solid var(--line); }
.cmd-list { display: grid; gap: 0; border-top: 1px solid var(--line); }
.cmd { padding: 18px 0; border-bottom: 1px solid var(--line); }
.cmd h3 { font-size: 16px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cmd h3 code { color: var(--syn-cmd); font-weight: 700; font-size: 15px; }
.tag { font-size: 11px; font-weight: 700; padding: 1px 6px; border: 1px solid var(--line-strong); border-radius: 4px; color: var(--ink-2); }
.cmd-meta { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 13.5px; color: var(--ink-2); margin: 6px 0; }
.cmd p { margin: 6px 0; }
.example { display: flex; align-items: flex-end; gap: 12px; margin-top: 10px; flex-wrap: wrap; }
.example pre { margin: 0; flex: 1; min-width: 220px; padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-s); overflow-x: auto; line-height: 1.6; }
.limits { border-collapse: collapse; width: 100%; margin-top: 12px; font-size: 14px; }
.limits caption { text-align: left; font-weight: 700; padding-bottom: 6px; }
.limits th, .limits td { text-align: left; vertical-align: top; padding: 8px 10px; border-top: 1px solid var(--line); }
.limits th { font-weight: 600; width: 40%; }

/* ---------- responsive ---------- */
@media (max-width: 1100px) {
  .speed-label { display: none; }
  .speed input { width: 84px; }
}
@media (max-width: 860px) {
  :root { --rail-h: 48px; }
  .rail { gap: 8px; padding: 0 8px; }
  .wordmark span { display: none; }
  .rail-nav a { padding: 0 10px; }
  .theme-label { display: none; }
  .theme-btn { width: 36px; justify-content: center; padding: 0; }
  .studio {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "switch" "pane" "dock";
  }
  .pane-switch {
    grid-area: switch; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 6px 8px;
    background: var(--panel-2); border-bottom: 1px solid var(--line);
  }
  .pane-switch button {
    display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px;
    border: 1px solid transparent; border-radius: var(--radius-s); background: transparent; font-weight: 600; color: var(--ink-2); cursor: pointer;
  }
  .pane-switch button[aria-selected="true"] { background: var(--panel); border-color: var(--line-strong); color: var(--ink); }
  .code-pane, .sheet-pane { grid-area: pane; border-right: 0; }
  .studio[data-pane="code"] .sheet-pane { visibility: hidden; pointer-events: none; }
  .studio[data-pane="sheet"] .code-pane { display: none; }
  .sheet-pane { padding: 6px; }
  .dock { border-right: 0; padding-bottom: env(safe-area-inset-bottom); }
  .run-bar { padding: 8px; gap: 4px; flex-wrap: nowrap; }
  .run-bar .btn { padding: 0 10px; }
  .run-bar .btn:not(.primary) span { display: none; }
  .run-bar .btn:not(.primary) { width: 40px; padding: 0; }
  .speed { margin-left: auto; }
  .speed input { width: 72px; }
  .status { min-height: 0; padding: 6px 10px; font-size: 13px; }
  .title-block { right: 10px; bottom: 10px; grid-template-columns: repeat(2, auto); font-size: 11px; }
  .title-block > div:nth-child(n) { border-right: 1px solid var(--ink); grid-column: auto; }
  .title-block > div:nth-child(2n+1):not(.tb-name) { border-right: 0; }
  .title-block > .tb-name { grid-column: 1 / -1; border-right: 0; }
  .title-block > .tb-wide, .title-block > div:last-child { grid-column: auto; }
  .title-block > div:nth-child(6), .title-block > div:nth-child(7) { display: none; }
  .view-tools { top: 10px; right: 10px; }
  .page { padding: 18px 14px 48px; gap: 20px; }
  .challenges, .help { grid-template-columns: 1fr; }
  .ch-list, .help-toc { position: static; }
  .ch-work { grid-template-columns: 1fr; }
  .ch-detail { padding: 16px; }
  .help-toc ol { display: flex; flex-wrap: wrap; border-left: 0; gap: 4px; }
  .help-toc a { border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; margin: 0; font-size: 13.5px; }
}
@media (max-width: 420px) {
  .code-bar { gap: 4px; padding: 6px; }
  #examples-btn span { display: none; }
  #examples-btn { width: 36px; padding: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

@media (forced-colors: active) {
  .ed-input { color: CanvasText; }
  .ed-hl { visibility: hidden; }
}

tool_use_result.content:
/* Logomocja — a drafting sheet with a live title block.
   Pen green is the action colour; copying-pencil violet marks only what is executing now. */

:root {
  color-scheme: light;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;

  --ground: #e9eee9;        /* app ground behind panels */
  --panel: #f8faf7;         /* editor and pages */
  --panel-2: #eef2ee;       /* bars */
  --sheet: #f6f8f2;         /* drafting sheet */
  --grid-minor: rgba(22, 134, 106, 0.09);
  --grid-major: rgba(22, 134, 106, 0.2);
  --grid-axis: rgba(27, 36, 34, 0.55);
  --frame: #9aa8a2;
  --ink: #1b2422;
  --ink-2: #4c5955;
  --ink-3: #6c7873;
  --line: #cfd8d3;
  --line-strong: #aab7b1;

  --rail: #123a31;
  --rail-ink: #e6f0eb;
  --rail-ink-2: #a9c4ba;
  --rail-hover: #1b4b40;

  --pen: #16866a;
  --action: #12765d;
  --action-hover: #0f6650;
  --on-action: #ffffff;
  --active: #6a3fb5;
  --active-soft: rgba(106, 63, 181, 0.12);
  --on-active: #ffffff;
  --error: #b3372c;
  --error-soft: #fbe9e6;
  --ok: #12765d;
  --ok-soft: #e3f2ec;
  --warn: #8a5a00;
  --warn-soft: #fbf0d9;

  --syn-cmd: #12765d;
  --syn-struct: #0d5a47;
  --syn-num: #9c4a14;
  --syn-name: #285a9c;
  --syn-str: #7a5a10;
  --syn-com: #6a7672;
  --syn-punct: #4c5955;
  --syn-rep: #6a3fb5;

  --radius: 8px;
  --radius-s: 6px;
  --shadow: 0 6px 24px rgba(18, 40, 33, 0.16), 0 1px 3px rgba(18, 40, 33, 0.12);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #2b6fb3;
  --rail-h: 52px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --ground: #0c1210;
    --panel: #131b18;
    --panel-2: #18221e;
    --sheet: #101714;
    --grid-minor: rgba(98, 214, 172, 0.07);
    --grid-major: rgba(98, 214, 172, 0.16);
    --grid-axis: rgba(220, 235, 228, 0.5);
    --frame: #3a4a44;
    --ink: #e2ebe6;
    --ink-2: #a8b8b1;
    --ink-3: #8a9a93;
    --line: #26332e;
    --line-strong: #3a4a44;
    --rail: #0b1f1a;
    --rail-ink: #e2efe9;
    --rail-ink-2: #93b3a7;
    --rail-hover: #143129;
    --pen: #3fbf98;
    --action: #1e9b7a;
    --action-hover: #23ad89;
    --on-action: #04140f;
    --active: #b49cf2;
    --active-soft: rgba(180, 156, 242, 0.16);
    --on-active: #1a1030;
    --error: #ff8f7f;
    --error-soft: #3a1c18;
    --ok: #5fd3ac;
    --ok-soft: #12302a;
    --warn: #f0c060;
    --warn-soft: #33290f;
    --syn-cmd: #5fd3ac;
    --syn-struct: #8fe6c6;
    --syn-num: #f0a46a;
    --syn-name: #8fb8f0;
    --syn-str: #e6c36a;
    --syn-com: #84958e;
    --syn-punct: #a8b8b1;
    --syn-rep: #c4b0f6;
    --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
    --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --ground: #0c1210;
  --panel: #131b18;
  --panel-2: #18221e;
  --sheet: #101714;
  --grid-minor: rgba(98, 214, 172, 0.07);
  --grid-major: rgba(98, 214, 172, 0.16);
  --grid-axis: rgba(220, 235, 228, 0.5);
  --frame: #3a4a44;
  --ink: #e2ebe6;
  --ink-2: #a8b8b1;
  --ink-3: #8a9a93;
  --line: #26332e;
  --line-strong: #3a4a44;
  --rail: #0b1f1a;
  --rail-ink: #e2efe9;
  --rail-ink-2: #93b3a7;
  --rail-hover: #143129;
  --pen: #3fbf98;
  --action: #1e9b7a;
  --action-hover: #23ad89;
  --on-action: #04140f;
  --active: #b49cf2;
  --active-soft: rgba(180, 156, 242, 0.16);
  --on-active: #1a1030;
  --error: #ff8f7f;
  --error-soft: #3a1c18;
  --ok: #5fd3ac;
  --ok-soft: #12302a;
  --warn: #f0c060;
  --warn-soft: #33290f;
  --syn-cmd: #5fd3ac;
  --syn-struct: #8fe6c6;
  --syn-num: #f0a46a;
  --syn-name: #8fb8f0;
  --syn-str: #e6c36a;
  --syn-com: #84958e;
  --syn-punct: #a8b8b1;
  --syn-rep: #c4b0f6;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.4);
  --focus: 0 0 0 2px var(--panel), 0 0 0 4px #8fb8f0;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
body {
  margin: 0;
  font: 15px/1.5 var(--font);
  color: var(--ink);
  background: var(--ground);
  font-variant-numeric: tabular-nums;
}
::selection { background: color-mix(in srgb, var(--pen) 28%, transparent); }
a { color: var(--syn-name); text-underline-offset: 3px; }
code, kbd, pre { font-family: var(--mono); font-size: 0.92em; }
h1, h2, h3 { line-height: 1.25; text-wrap: balance; margin: 0; }
button, input, select { font: inherit; color: inherit; }
:focus-visible { outline: none; box-shadow: var(--focus); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip {
  position: absolute; left: 8px; top: -48px; z-index: 50; padding: 8px 12px; border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
}
.skip:focus { top: 8px; }
* { scrollbar-color: var(--line-strong) transparent; scrollbar-width: thin; }
svg.ico { width: 18px; height: 18px; flex: none; }

/* ---------- rail ---------- */
.rail {
  height: var(--rail-h);
  display: flex; align-items: center; gap: 24px;
  padding: 0 16px;
  background: var(--rail);
  color: var(--rail-ink);
  position: sticky; top: 0; z-index: 20;
}
.wordmark {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--rail-ink); text-decoration: none;
  font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
  padding: 6px 4px; border-radius: var(--radius-s);
}
.wordmark .mark { color: #3fbf98; transform: rotate(0deg); }
.rail :focus-visible { box-shadow: 0 0 0 2px var(--rail), 0 0 0 4px #9fd8c4; }
.rail-nav { display: flex; gap: 2px; height: 100%; }
.rail-nav a {
  display: inline-flex; align-items: center; padding: 0 12px; height: 100%;
  color: var(--rail-ink-2); text-decoration: none; font-weight: 500;
  border-bottom: 2px solid transparent; border-top: 2px solid transparent;
}
.rail-nav a:hover { color: var(--rail-ink); background: var(--rail-hover); }
.rail-nav a[aria-current="page"] { color: var(--rail-ink); border-bottom-color: #3fbf98; }
.theme-btn {
  margin-left: auto; display: inline-flex; align-items: center; gap: 6px;
  background: transparent; border: 1px solid rgba(255, 255, 255, 0.18); color: var(--rail-ink);
  height: 34px; padding: 0 10px; border-radius: var(--radius-s); cursor: pointer;
}
.theme-btn:hover { background: var(--rail-hover); }

main { outline: none; }

/* ---------- buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 36px; padding: 0 12px;
  border: 1px solid var(--line-strong); border-radius: var(--radius-s);
  background: var(--panel); color: var(--ink);
  font-weight: 500; cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn:hover { background: var(--panel-2); border-color: var(--ink-3); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; }
.btn.primary { background: var(--action); border-color: var(--action); color: var(--on-action); font-weight: 600; }
.btn.primary:hover { background: var(--action-hover); border-color: var(--action-hover); }
.btn.ghost { border-color: transparent; background: transparent; }
.btn.ghost:hover { background: var(--panel-2); }
.btn.icon-only { width: 36px; padding: 0; }
.btn.small { height: 30px; padding: 0 10px; font-size: 13.5px; }
.link-btn {
  background: none; border: 0; padding: 2px 4px; color: inherit; font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px; cursor: pointer; border-radius: 4px;
}

/* ---------- studio ---------- */
body[data-route="studio"] { height: 100dvh; overflow: hidden; }
.studio {
  height: calc(100dvh - var(--rail-h));
  display: grid;
  grid-template-columns: minmax(340px, 40%) 1fr;
  grid-template-rows: 1fr auto;
  grid-template-areas: "code sheet" "dock sheet";
}
.pane-switch { display: none; }
.code-pane {
  grid-area: code; min-height: 0; display: flex; flex-direction: column;
  background: var(--panel); border-right: 1px solid var(--line);
}
.code-bar {
  display: flex; align-items: center; gap: 8px; padding: 8px 10px;
  background: var(--panel-2); border-bottom: 1px solid var(--line);
}
.bar-gap { flex: 1; }
.file-actions { display: flex; gap: 2px; }
.file-actions .btn { border-color: transparent; background: transparent; }
.file-actions .btn:hover { background: var(--panel); border-color: var(--line-strong); }
.seg { display: inline-flex; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; height: 36px; }
.seg button {
  border: 0; background: var(--panel); padding: 0 14px; font-weight: 600; cursor: pointer; color: var(--ink-2);
}
.seg button + button { border-left: 1px solid var(--line-strong); }
.seg button[aria-checked="true"] { background: var(--ink); color: var(--panel); }
.seg button:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.editor-slot { flex: 1; min-height: 0; display: flex; }

.dock { grid-area: dock; background: var(--panel); border-right: 1px solid var(--line); border-top: 1px solid var(--line); }
.status {
  display: flex; align-items: flex-start; gap: 8px; padding: 8px 12px; min-height: 40px;
  font-size: 13.5px; color: var(--ink-2); border-bottom: 1px solid var(--line);
}
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--line-strong); margin-top: 6px; flex: none; }
.status-text { flex: 1; }
.status[data-kind="run"] .status-dot, .status[data-kind="pause"] .status-dot { background: var(--active); }
.status[data-kind="ok"] .status-dot { background: var(--ok); }
.status[data-kind="warn"] { color: var(--warn); background: var(--warn-soft); }
.status[data-kind="warn"] .status-dot { background: var(--warn); }
.status[data-kind="error"] { color: var(--error); background: var(--error-soft); }
.status[data-kind="error"] .status-dot { background: var(--error); }
.status[data-kind="error"] .status-text { color: var(--ink); }
.run-bar { display: flex; align-items: center; gap: 6px; padding: 10px; flex-wrap: wrap; }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--ink-2); }
.speed input { width: 110px; accent-color: var(--action); }
.studio[data-run="running"] [data-act="run"] { box-shadow: inset 0 -3px 0 var(--active); }

/* ---------- editor ---------- */
.editor { flex: 1; min-height: 0; display: flex; position: relative; background: var(--panel); }
.ed-scroll { flex: 1; overflow: auto; display: flex; align-items: flex-start; min-height: 0; }
.ed-gutter {
  position: sticky; left: 0; z-index: 2; flex: none;
  min-width: 44px; padding: 12px 8px 40px 0; min-height: 100%;
  background: var(--panel); border-right: 1px solid var(--line);
  font: 13.5px/21px var(--mono); color: var(--ink-3); text-align: right;
  user-select: none;
}
.ed-gutter span { display: block; }
.ed-gutter .g-err { color: var(--error); font-weight: 700; }
.ed-code { position: relative; flex: 1; min-width: max-content; min-height: 100%; }
.ed-hl, .ed-input {
  margin: 0; padding: 12px 16px 40px 12px; border: 0;
  font: 13.5px/21px var(--mono); tab-size: 2; white-space: pre; letter-spacing: 0;
}
.ed-hl { color: var(--ink); pointer-events: none; min-height: 100%; position: relative; z-index: 1; }
.ed-input {
  position: absolute; inset: 0; width: 100%; height: 100%; resize: none; overflow: hidden;
  background: transparent; color: transparent; caret-color: var(--ink); z-index: 2; outline: none;
}
.ed-input::selection { background: color-mix(in srgb, var(--pen) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px #2b6fb3; }
.ed-band {
  position: absolute; left: 0; right: 0; z-index: 0;
  background: var(--active-soft); box-shadow: inset 3px 0 0 var(--active);
}
.ed-bubble {
  position: absolute; z-index: 3; left: calc(12px + var(--col, 0) * 1ch); max-width: min(46ch, 80vw);
  padding: 6px 10px; border-radius: var(--radius-s);
  background: var(--error); color: #fff; font: 600 12.5px/1.4 var(--font); white-space: normal;
  box-shadow: var(--shadow); pointer-events: none;
}
:root[data-theme="dark"] .ed-bubble { color: #2a0d09; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .ed-bubble { color: #2a0d09; } }
.ed-bubble::before {
  content: ""; position: absolute; left: 8px; top: -5px; width: 10px; height: 10px;
  background: inherit; transform: rotate(45deg);
}
.t-k { color: var(--syn-cmd); font-weight: 600; }
.t-k2 { color: var(--syn-struct); font-weight: 700; }
.t-v { color: var(--syn-rep); font-weight: 600; }
.t-n { color: var(--syn-name); }
.t-num { color: var(--syn-num); }
.t-s { color: var(--syn-str); box-shadow: inset 0 -3px 0 var(--sw, transparent); }
.t-bad { text-decoration: underline wavy var(--error); }
.t-c { color: var(--syn-com); font-style: italic; }
.t-b { color: var(--ink); font-weight: 700; }
.t-p, .t-o { color: var(--syn-punct); }
.t-x { color: var(--error); }
.t-err { text-decoration: underline wavy var(--error) 1.5px; text-underline-offset: 4px; background: color-mix(in srgb, var(--error) 14%, transparent); border-radius: 2px; }

/* ---------- sheet ---------- */
.sheet-pane { grid-area: sheet; min-width: 0; min-height: 0; padding: 12px; background: var(--ground); display: flex; }
.sheet {
  position: relative; flex: 1; min-height: 0; overflow: hidden;
  background: var(--sheet); border: 1px solid var(--frame); border-radius: 2px;
  box-shadow: 0 1px 2px rgba(18, 40, 33, 0.08);
}
.sheet::after { content: ""; position: absolute; inset: 6px; border: 1px solid var(--frame); pointer-events: none; opacity: 0.6; }
.sheet-host { position: absolute; inset: 0; }
.sheet-host[hidden] { display: none; }
.sheet-canvas { display: block; touch-action: none; cursor: grab; outline: none; }
.sheet-canvas:active { cursor: grabbing; }
.sheet-canvas:focus-visible { box-shadow: inset 0 0 0 3px #2b6fb3; }
.nogl { position: absolute; inset: 0; display: grid; place-items: center; padding: 24px; }
.nogl[hidden] { display: none; }
.nogl p { max-width: 42ch; margin: 0; padding: 16px 18px; border: 1px solid var(--line-strong); background: var(--panel); border-radius: var(--radius); }
.view-tools {
  position: absolute; top: 16px; right: 16px; z-index: 3;
  display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line-strong);
  border-radius: var(--radius-s); box-shadow: 0 2px 8px rgba(18, 40, 33, 0.12); overflow: hidden;
}
.tool { width: 38px; height: 38px; display: grid; place-items: center; border: 0; background: none; cursor: pointer; color: var(--ink); }
.tool + .tool { border-top: 1px solid var(--line); }
.tool:hover { background: var(--panel-2); }
.tool:focus-visible { box-shadow: inset 0 0 0 2px #2b6fb3; }
.tool[hidden] { display: none; }

/* The title block: a ruled drafting tabliczka holding live readouts. */
.title-block {
  position: absolute; right: 16px; bottom: 16px; z-index: 3; margin: 0;
  display: grid; grid-template-columns: repeat(4, auto);
  background: var(--sheet); border: 1.5px solid var(--ink);
  font-size: 12px; line-height: 1.25; pointer-events: none;
}
.title-block > div { padding: 4px 8px 5px; border-right: 1px solid var(--ink); border-top: 1px solid var(--ink); min-width: 64px; }
.title-block > div:nth-child(4n), .title-block > .tb-name { border-right: 0; }
.title-block > .tb-name { grid-column: 1 / -1; border-top: 0; display: flex; align-items: baseline; gap: 10px; padding: 6px 8px; }
.title-block > .tb-wide { grid-column: span 2; }
.title-block > div:nth-child(5) { border-right: 1px solid var(--ink); }
.title-block > div:last-child { border-right: 0; grid-column: span 2; }
.title-block dt { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ink-2); }
.title-block dd { margin: 0; font-weight: 600; white-space: nowrap; }
.title-block .tb-name dd { font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
[data-tb="pen"]::before { content: ""; display: inline-block; width: 10px; height: 10px; margin-right: 6px; vertical-align: -1px; background: var(--pen, #16866a); border: 1px solid var(--ink); }
.title-block dd[data-tb="pen"] { --pen: #16866a; }
.studio[data-run="running"] .title-block, .studio[data-run="paused"] .title-block { border-color: var(--active); }
.studio[data-run="running"] .title-block [data-tb="pos"], .studio[data-run="paused"] .title-block [data-tb="pos"] { color: var(--active); }

/* ---------- popovers ---------- */
.pop {
  margin: auto; padding: 0; border: 1px solid var(--line-strong); border-radius: 12px;
  background: var(--panel); color: var(--ink); box-shadow: var(--shadow);
  width: min(760px, calc(100vw - 24px)); max-height: min(720px, calc(100dvh - 32px)); overflow: auto;
}
.pop::backdrop { background: rgba(10, 20, 17, 0.32); }
.pop-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px 6px 20px; position: sticky; top: 0; background: var(--panel); z-index: 1; }
.pop-head h2 { font-size: 18px; }
.pop-note { margin: 0 20px 12px; color: var(--ink-2); font-size: 13.5px; }
.ex-grid {
  list-style: none; margin: 0; padding: 0 16px 16px;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 10px;
}
.ex-cell {
  width: 100%; height: 100%; display: flex; flex-direction: column; gap: 2px; text-align: left;
  padding: 6px 6px 10px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); cursor: pointer;
}
.ex-cell:hover { border-color: var(--pen); }
.ex-thumb { width: 100%; height: 104px; display: block; border-radius: 4px; margin-bottom: 6px; background: var(--sheet); }
.ex-name { display: flex; justify-content: space-between; align-items: baseline; font-weight: 650; padding: 0 4px; }
.ex-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); border: 1px solid var(--line-strong); border-radius: 4px; padding: 0 4px; }
.ex-blurb { font-size: 12.5px; color: var(--ink-2); padding: 0 4px; }
.restore { margin: 0 16px 16px; }
.restore[hidden] { display: none; }
.shortcuts-pop { width: min(480px, calc(100vw - 24px)); }
.keys { margin: 0; padding: 4px 20px 18px; display: grid; gap: 8px; }
.keys > div { display: grid; grid-template-columns: minmax(160px, auto) 1fr; gap: 12px; align-items: baseline; }
.keys dt, .keys dd { margin: 0; }
kbd {
  display: inline-block; padding: 1px 6px; border: 1px solid var(--line-strong); border-bottom-width: 2px;
  border-radius: 4px; background: var(--panel-2); font-size: 12.5px; white-space: nowrap;
}

/* ---------- toasts ---------- */
.toasts { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); z-index: 60; display: grid; gap: 8px; width: min(520px, calc(100vw - 24px)); }
.toast {
  display: flex; align-items: center; gap: 10px; padding: 10px 8px 10px 14px;
  background: var(--ink); color: var(--panel); border-radius: var(--radius); box-shadow: var(--shadow);
  animation: toast-in 200ms cubic-bezier(0.16, 1, 0.3, 1);
}
.toast p { margin: 0; flex: 1; font-size: 14px; }
.toast .btn { background: transparent; color: var(--panel); border-color: color-mix(in srgb, var(--panel) 45%, transparent); }
.toast .btn:hover { background: color-mix(in srgb, var(--panel) 14%, transparent); }
.toast-x { background: none; border: 0; color: inherit; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 4px; cursor: pointer; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- pages ---------- */
.page { max-width: 1200px; margin: 0 auto; padding: 28px 24px 64px; display: grid; gap: 32px; }
.page h1 { font-size: 24px; letter-spacing: -0.015em; }

.challenges { grid-template-columns: 260px 1fr; align-items: start; }
.ch-list { position: sticky; top: calc(var(--rail-h) + 24px); }
.ch-count { color: var(--ink-2); margin: 4px 0 14px; font-size: 14px; }
.ch-list ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.ch-list a {
  display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: var(--radius-s); color: var(--ink); text-decoration: none;
}
.ch-list a:hover { background: var(--panel-2); }
.ch-list a[aria-current="page"] { background: var(--panel); box-shadow: inset 0 0 0 1px var(--line-strong); font-weight: 600; }
.ch-state { width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--line-strong); display: grid; place-items: center; }
.ch-state.is-done { background: var(--ok); border-color: var(--ok); color: var(--panel); }
.ch-state svg { width: 14px; height: 14px; }
.ch-li-mode { font-size: 11px; font-weight: 700; color: var(--ink-2); }
.ch-detail { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 24px; min-width: 0; }
.ch-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.ch-name { font-size: 22px; letter-spacing: -0.01em; }
.ch-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 700; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-strong); color: var(--ink-2); }
.ch-badge.is-done { background: var(--ok-soft); border-color: var(--ok); color: var(--ok); }
.ch-badge svg { width: 14px; height: 14px; }
.ch-task { font-size: 16px; max-width: 65ch; margin: 10px 0 8px; }
.ch-hint { margin-bottom: 18px; color: var(--ink-2); }
.ch-hint summary { cursor: pointer; font-weight: 600; width: max-content; border-radius: 4px; }
.ch-hint p { margin: 6px 0 0; max-width: 65ch; }
.ch-work { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; }
.ch-figure { margin: 0; }
.ch-canvas { width: 100%; aspect-ratio: 4 / 3; display: block; border: 1px solid var(--frame); background: var(--sheet); }
.ch-figure figcaption { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 13px; color: var(--ink-2); }
.key-target, .key-attempt { display: inline-block; width: 22px; height: 0; border-top: 2px dashed var(--ink-2); }
.key-attempt { border-top: 3px solid var(--pen); margin-left: 12px; }
.ch-code { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.ch-code .editor { min-height: 240px; border: 1px solid var(--line-strong); border-radius: var(--radius-s); overflow: hidden; }
.ch-code .ed-scroll { max-height: 420px; }
.ch-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ch-result:empty { display: none; }
.ch-result { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius); }
.ch-result p { margin: 0; }
.ch-result[data-kind="ok"] { background: var(--ok-soft); color: var(--ink); }
.ch-result[data-kind="ok"] svg { color: var(--ok); }
.ch-result[data-kind="fail"] { background: var(--error-soft); color: var(--ink); }
.ch-result[data-kind="fail"] svg { color: var(--error); }

.help { grid-template-columns: 240px minmax(0, 1fr); align-items: start; }
.help-toc { position: sticky; top: calc(var(--rail-h) + 24px); }
.help-toc h1 { font-size: 20px; margin-bottom: 12px; }
.help-toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; border-left: 1px solid var(--line); }
.help-toc a { display: block; padding: 5px 12px; color: var(--ink-2); text-decoration: none; margin-left: -1px; border-left: 2px solid transparent; }
.help-toc a:hover { color: var(--ink); border-left-color: var(--pen); }
.help-body { max-width: 80ch; display: grid; gap: 40px; }
.help-body section { scroll-margin-top: calc(var(--rail-h) + 20px); }
.help-body h2 { font-size: 21px; letter-spacing: -0.01em; margin: 0 0 10px; outline: none; }
.help-body p, .help-body li { max-width: 70ch; }
.help-body ul { padding-left: 20px; }
.help-body li { margin: 4px 0; }
.help-body :not(pre) > code { background: var(--panel-2); padding: 1px 5px; border-radius: 4px; border: 1px solid var(--line); }
.cmd-list { display: grid; gap: 0; border-top: 1px solid var(--line); }
.cmd { padding: 18px 0; border-bottom: 1px solid var(--line); }
.cmd h3 { font-size: 16px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cmd h3 code { color: var(--syn-cmd); font-weight: 700; font-size: 15px; }
.tag { font-size: 11px; font-weight: 700; padding: 1px 6px; border: 1px solid var(--line-strong); border-radius: 4px; color: var(--ink-2); }
.cmd-meta { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 13.5px; color: var(--ink-2); margin: 6px 0; }
.cmd p { margin: 6px 0; }
.example { display: flex; align-items: flex-end; gap: 12px; margin-top: 10px; flex-wrap: wrap; }
.example pre { margin: 0; flex: 1; min-width: 220px; padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-s); overflow-x: auto; line-height: 1.6; }
.limits { border-collapse: collapse; width: 100%; margin-top: 12px; font-size: 14px; }
.limits caption { text-align: left; font-weight: 700; padding-bottom: 6px; }
.limits th, .limits td { text-align: left; vertical-align: top; padding: 8px 10px; border-top: 1px solid var(--line); }
.limits th { font-weight: 600; width: 40%; }

/* ---------- responsive ---------- */
@media (max-width: 1100px) {
  .speed-label { display: none; }
  .speed input { width: 84px; }
}
@media (max-width: 860px) {
  :root { --rail-h: 48px; }
  .rail { gap: 8px; padding: 0 8px; }
  .wordmark span { display: none; }
  .rail-nav a { padding: 0 10px; }
  .theme-label { display: none; }
  .theme-btn { width: 36px; justify-content: center; padding: 0; }
  .studio {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "switch" "pane" "dock";
  }
  .pane-switch {
    grid-area: switch; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 6px 8px;
    background: var(--panel-2); border-bottom: 1px solid var(--line);
  }
  .pane-switch button {
    display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px;
    border: 1px solid transparent; border-radius: var(--radius-s); background: transparent; font-weight: 600; color: var(--ink-2); cursor: pointer;
  }
  .pane-switch button[aria-selected="true"] { background: var(--panel); border-color: var(--line-strong); color: var(--ink); }
  .code-pane, .sheet-pane { grid-area: pane; border-right: 0; }
  .studio[data-pane="code"] .sheet-pane { visibility: hidden; pointer-events: none; }
  .studio[data-pane="sheet"] .code-pane { display: none; }
  .sheet-pane { padding: 6px; }
  .dock { border-right: 0; padding-bottom: env(safe-area-inset-bottom); }
  .run-bar { padding: 8px; gap: 4px; flex-wrap: nowrap; }
  .run-bar .btn { padding: 0 10px; }
  .run-bar .btn:not(.primary) span { display: none; }
  .run-bar .btn:not(.primary) { width: 40px; padding: 0; }
  .speed { margin-left: auto; }
  .speed input { width: 72px; }
  .status { min-height: 0; padding: 6px 10px; font-size: 13px; }
  .title-block { right: 10px; bottom: 10px; grid-template-columns: repeat(2, auto); font-size: 11px; }
  .title-block > div:nth-child(n) { border-right: 1px solid var(--ink); grid-column: auto; }
  .title-block > div:nth-child(2n+1):not(.tb-name) { border-right: 0; }
  .title-block > .tb-name { grid-column: 1 / -1; border-right: 0; }
  .title-block > .tb-wide, .title-block > div:last-child { grid-column: auto; }
  .title-block > div:nth-child(6), .title-block > div:nth-child(7) { display: none; }
  .view-tools { top: 10px; right: 10px; }
  .page { padding: 18px 14px 48px; gap: 20px; }
  .challenges, .help { grid-template-columns: 1fr; }
  .ch-list, .help-toc { position: static; }
  .ch-work { grid-template-columns: 1fr; }
  .ch-detail { padding: 16px; }
  .help-toc ol { display: flex; flex-wrap: wrap; border-left: 0; gap: 4px; }
  .help-toc a { border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; margin: 0; font-size: 13.5px; }
}
@media (max-width: 420px) {
  .code-bar { gap: 4px; padding: 6px; }
  #examples-btn span { display: none; }
  #examples-btn { width: 36px; padding: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

@media (forced-colors: active) {
  .ed-input { color: CanvasText; }
  .ed-hl { visibility: hidden; }
}

