await p.click('#kod'); await p.keyboard.press('End'); await p.keyboard.type(' ');
log('edited while running:', await status());
await p.keyboard.press('Control+Enter'); await p.$eval('.speed input', el => { el.value = '10'; el.dispatchEvent(new Event('input', { bubbles: true })); });
await p.keyboard.press('Control+Enter'); await p.waitForTimeout(200);
log('ctrl+enter:', await status());
await p.keyboard.press('Control+Shift+Backspace'); log('reset:', await status(), await tb('segs'));
// persistence
await p.reload(); await p.waitForFunction(() => window.logomocja);
log('draft after reload:', JSON.stringify(await p.inputValue('#kod')));
// example with draft protection
await p.click('#examples-btn'); await p.click('[data-example="gwiazda"]'); await p.waitForTimeout(300);
log('example loaded:', await tb('name'), (await p.inputValue('#kod')).slice(0, 20), 'toast:', await p.textContent('.toast p'));
await p.click('.toast .btn'); await p.waitForTimeout(100);
log('restored:', JSON.stringify(await p.inputValue('#kod')));
// 3D draft separate
await p.click('[data-mode="3d"]'); await p.waitForTimeout(300);
log('3d draft:', (await p.inputValue('#kod')).slice(0, 25));
await p.click('[data-mode="2d"]'); log('2d draft back:', JSON.stringify(await p.inputValue('#kod')));
// link
await p.click('[data-act="link"]'); await p.waitForTimeout(200);
const link = await p.evaluate(() => navigator.clipboard.readText());
log('link:', link.slice(0, 90));
const p2 = await ctx.newPage(); await p2.goto(link); await p2.waitForFunction(() => window.logomocja); await p2.waitForTimeout(400);
log('permalink opened:', await p2.inputValue('#kod'), await p2.textContent('[data-tb="segs"]'), await p2.textContent('.status-text'), 'hash', await p2.evaluate(() => location.hash));
// downloads
let [dl] = await Promise.all([p.waitForEvent('download'), p.click('[data-act="save"]')]);
log('download:', dl.suggestedFilename(), fs.readFileSync(await dl.path(), 'utf8').slice(0, 30));
[dl] = await Promise.all([p.waitForEvent('download'), p.click('[data-act="png"]')]);
log('png:', dl.suggestedFilename(), fs.statSync(await dl.path()).size);
fs.writeFileSync('/tmp/schody-3d.logo', 'kolor "#2b6fb3"\npowtorz 4 [np 50 gora 90]\n');
await p.setInputFiles('#file-input', '/tmp/schody-3d.logo'); await p.waitForTimeout(500);
log('file open:', await tb('mode'), await tb('name'), await tb('segs'));
[dl] = await Promise.all([p.waitForEvent('download'), p.click('[data-act="png"]')]);
log('png3d:', dl.suggestedFilename(), fs.statSync(await dl.path()).size);
// theme
const th = async () => p.evaluate(() => document.documentElement.dataset.theme || 'system');
await p.click('.theme-btn'); const t1 = await th(); await p.click('.theme-btn'); const t2 = await th(); await p.click('.theme-btn'); log('theme cycle:', t1, t2, await th());
// challenge
await p.goto(url + '#/wyzwania/trojkat'); await p.waitForTimeout(200);
await p.click('#rozwiazanie'); await p.keyboard.type('powtorz 3 [np 120 lw 120]');
await p.click('[data-act="check"]'); log('challenge wrong:', await p.textContent('.ch-result'));
await p.click('#rozwiazanie'); await p.keyboard.press('Control+A'); await p.keyboard.type('np 120 pw 120 np 60 np 60 pw 120 powtorz 1 [np 120]');
await p.keyboard.press('Control+Enter'); log('challenge right:', await p.textContent('.ch-result'), await p.textContent('.ch-count'));
await p.screenshot({ path: '/work/.impeccable/review/desktop-challenge-pass.png' });
await p.click('#rozwiazanie'); await p.keyboard.press('Control+A'); await p.keyboard.type('np 10 -5');
await p.click('[data-act="check"]'); log('challenge err:', await p.textContent('.ch-result'));
await p.reload(); await p.waitForTimeout(200); log('progress after reload:', await p.textContent('.ch-count'));
