await p.goto(url + '#/pomoc'); await p.waitForTimeout(200);
await p.click('[data-try]'); await p.waitForTimeout(300); log('help try:', await p.evaluate(() => location.hash), await tb('segs'));
await p.screenshot({ path: '/work/.impeccable/review/desktop-help-try.png' });
// keyboard focus
await p.goto(url); await p.waitForTimeout(200);
const order = [];
for (let i = 0; i < 22; i++) { await p.keyboard.press('Tab'); order.push(await p.evaluate(() => { const a = document.activeElement; return (a.getAttribute('aria-label') || a.textContent || a.tagName).trim().slice(0, 18); })); }
log('tab order:', order.join(' | '));
log('errors', errs);
const nb = await chromium.launch({ args: ['--disable-webgl', '--disable-3d-apis'] });
const np = await nb.newPage(); await np.goto(url); await np.waitForFunction(() => window.logomocja);
const r = await np.evaluate(() => window.logomocja.open('gora 90 np 50', '3d'));
log('noGL open:', r.segments.length, r.error, await np.textContent('.nogl p'));
await np.screenshot({ path: '/work/.impeccable/review/nogl.png' });
await nb.close(); await b.close();
