import { chromium } from 'playwright';
const b = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
const ctx = await b.newContext({ viewport: { width: 1280, height: 800 } });
const p = await ctx.newPage();
p.on('crash', () => console.log('PAGE CRASH'));
p.on('pageerror', e => console.log('pageerror', String(e)));
b.on('disconnected', () => console.log('BROWSER DISCONNECTED'));
await p.goto('http://localhost:8765/Logomocja/builds/x/'); await p.waitForFunction(() => window.logomocja);
const ids = await p.$$eval('[data-example]', bs => bs.map(b => b.dataset.example));
for (const id of ids) {
  console.log('load', id);
  await p.click('#examples-btn', { timeout: 5000 });
  await p.click(`[data-example="${id}"]`, { timeout: 5000 });
  await p.waitForTimeout(200);
}
console.log(await p.textContent('[data-tb="name"]'), await p.textContent('[data-tb="mode"]'));
await p.screenshot({ path: '/work/.impeccable/review/last-example.png' });
await b.close();
EOF
cd /tmp/pw && LD_LIBRARY_PATH=/tmp/libs/root/usr/lib/aarch64-linux-gnu:/tmp/libs/root/lib/aarch64-linux-gnu FONTCONFIG_FILE=/tmp/libs/fonts.conf timeout 100 node all.mjs 2>&1 | grep -v "^    at" | head -30

